create table brand_learnings(id text primary key,workspace_id text not null,brand_id text not null,statement text not null,interpretation text not null,confidence double precision not null check(confidence between 0 and 1),period_from timestamptz not null,period_to timestamptz not null,applicability jsonb not null,evidence jsonb not null,contradictions jsonb not null default '[]',status text not null check(status in ('candidate','accepted','rejected','superseded')),version integer not null check(version>0),created_at timestamptz not null,decided_by text,decided_at timestamptz,rejection_reason text,superseded_by_id text,foreign key(workspace_id,brand_id) references brands(workspace_id,id),check(jsonb_array_length(evidence)>0));
create index brand_learnings_scope on brand_learnings(brand_id,status,created_at desc);
create table content_experiments(id text primary key,workspace_id text not null,brand_id text not null,hypothesis text not null,variants jsonb not null,primary_metric text not null,status text not null check(status in ('draft','completed')),created_at timestamptz not null,winner_variant_id text,result_summary text,evidence_observation_ids jsonb,completed_at timestamptz,foreign key(workspace_id,brand_id) references brands(workspace_id,id),check(jsonb_array_length(variants)>=2));
create index content_experiments_scope on content_experiments(brand_id,status,created_at desc);
